import{_ as e,o as n,c as t,a2 as i}from"./chunks/framework.CCtxZRER.js";const m=JSON.parse('{"title":"Kode Barang","description":"Perbedaan kode barang, spesifikasi, dan identifikasi, dengan contoh bearing 6205-2RS.","frontmatter":{"title":"Kode Barang","description":"Perbedaan kode barang, spesifikasi, dan identifikasi, dengan contoh bearing 6205-2RS.","status":"ditinjau","dasar":"materi presentasi Gudang Teknik (slide 11)","catatan_status":"Contoh kode di halaman ini berasal dari materi presentasi. Format kode resmi di sistem gudang perlu dikonfirmasi pembimbing.","diperbarui":"2026-10-13T00:00:00.000Z","kategori":"Gudang Teknik","sumber":["ppt-gudang-teknik"],"kata_kunci":["kode barang","spesifikasi","identifikasi","label","part number","bearing","6205-2RS","BRG-MEC-001","salah ambil"]},"headers":[],"relativePath":"divisi/kode-barang.md","filePath":"divisi/kode-barang.md"}'),r={name:"divisi/kode-barang.md"};function s(d,a,o,l,g,k){return n(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="kode-barang" tabindex="-1">Kode Barang <a class="header-anchor" href="#kode-barang" aria-label="Permalink to &quot;Kode Barang&quot;">​</a></h1><p class="lead">Kode barang, spesifikasi, dan identifikasi adalah tiga unsur yang membuat setiap material bisa dikenali, dicatat, disimpan, dan ditemukan dengan cepat. Ketiganya juga mengurangi kesalahan saat barang masuk maupun keluar.</p><h2 id="tiga-unsur" tabindex="-1">Tiga unsur <a class="header-anchor" href="#tiga-unsur" aria-label="Permalink to &quot;Tiga unsur&quot;">​</a></h2><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Unsur</th><th>Penjelasan</th><th>Contoh</th></tr></thead><tbody><tr><td data-label="Unsur"><strong>Kode barang</strong></td><td data-label="Penjelasan">Nomor atau kode unik yang menjadi identitas satu jenis material</td><td data-label="Contoh"><code>BRG-MEC-001</code></td></tr><tr><td data-label="Unsur"><strong>Spesifikasi barang</strong></td><td data-label="Penjelasan">Informasi teknis yang menjelaskan karakteristik material</td><td data-label="Contoh">Bearing, 6205-2RS, 25 × 52 × 15 mm</td></tr><tr><td data-label="Unsur"><strong>Identifikasi barang</strong></td><td data-label="Penjelasan">Proses mengenali barang berdasarkan kode, nama, label, dan karakteristiknya</td><td data-label="Contoh"><code>BRG-MEC-001</code> – Bearing 6205-2RS</td></tr></tbody></table><h2 id="membaca-contoh" tabindex="-1">Membaca contoh <a class="header-anchor" href="#membaca-contoh" aria-label="Permalink to &quot;Membaca contoh&quot;">​</a></h2><figure><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BRG-MEC-001  –  Bearing 6205-2RS  –  25 × 52 × 15 mm</span></span>
<span class="line"><span>└─ kode ──┘     └─ nama &amp; tipe ─┘    └─ ukuran ─────┘</span></span></code></pre></div><figcaption>Struktur contoh label barang dari materi Gudang Teknik.</figcaption></figure><p>Pada contoh di atas, bagian <code>MEC</code> tampaknya menunjukkan kelompok <em>Mechanical Parts</em>, dan <code>001</code> adalah nomor urut. Pola ini perlu dicocokkan dengan aturan pengodean resmi di gudang sebelum dijadikan pegangan.</p><p>Ukuran <strong>25 × 52 × 15 mm</strong> pada bearing umumnya berarti diameter dalam × diameter luar × tebal. Akhiran <strong>2RS</strong> umumnya berarti bearing memakai seal karet di kedua sisi.</p><h2 id="kesalahan-yang-sering-terjadi" tabindex="-1">Kesalahan yang sering terjadi <a class="header-anchor" href="#kesalahan-yang-sering-terjadi" aria-label="Permalink to &quot;Kesalahan yang sering terjadi&quot;">​</a></h2><ul><li><strong>Mengandalkan nama saja.</strong> &quot;Bearing&quot; saja ada puluhan ukuran. Selalu cocokkan kode <strong>dan</strong> spesifikasinya.</li><li><strong>Label rusak atau hilang.</strong> Jangan menebak. Pisahkan barangnya dan laporkan ke pembimbing.</li><li><strong>Satu barang, dua kode.</strong> Jika menemukan barang identik dengan kode berbeda, laporkan. Duplikasi kode membuat stok tampak lebih sedikit dari kenyataannya.</li><li><strong>Satuan berbeda.</strong> Pastikan satuan di catatan (pcs, set, meter, liter) sama dengan satuan saat barang dihitung.</li></ul><p>Latihan langkah demi langkah ada di tutorial <a href="/WareHouse/tutorial/membaca-kode-barang">Membaca Kode &amp; Spesifikasi</a>.</p>`,11)])])}const b=e(r,[["render",s]]);export{m as __pageData,b as default};
